ruleContent.content:
function getImgList(){
    var p = "cp=\"(.*?)\"";
    var str = html.match(p)[1];

    if (str!=null){
        var list = eval("("+window.atob(str)+")").toString().split(",");
        var piclist = new Array([list.length]);
        for (var i = 0; i < list.length; i++) {
            piclist[i] = "http://f.pufei.net/" + list[i];
        }
        return piclist;
    }else {
        return null;
    }

};

function getImgList(){
    var p = "chapterImages = \\[(.*?)\\]";
    var p1 = "chapterPath = \"(.*?)\"";
    var chapterPath  = html.match(p1)[1];
    var path = html.match(p)[1].replace(/\"/g, "").split(",");
    var piclist = new Array([path.length]);
    for (var i = 0; i < path.length; i++) {
        piclist[i] = "https://img001.yayxcc.com/"+chapterPath + path[i];
    }
    return piclist;
}

